// Command wordfreq reads standard input and prints the 10 most frequent
// ASCII-letter words (case-folded), ordered by count descending, then by
// word ascending.
package main

import (
	"bufio"
	"cmp"
	"fmt"
	"io"
	"os"
	"slices"
	"strconv"
)

const (
	topN      = 10
	readChunk = 1 << 16
)

// WordCount is a word together with the number of times it occurred.
type WordCount struct {
	Word  string
	Count int
}

func isLetter(c byte) bool {
	return (c|0x20)-'a' < 26
}

// CountWords tallies the case-folded words in r. A word is a maximal run of
// ASCII letters; every other byte is a separator.
func CountWords(r io.Reader) (map[string]int, error) {
	counts := make(map[string]int)
	buf := make([]byte, readChunk)
	var pending []byte // a word that may continue into the next chunk

	for {
		n, err := r.Read(buf)
		chunk := buf[:n]
		i := 0
		for i < len(chunk) {
			if !isLetter(chunk[i]) {
				if len(pending) > 0 {
					counts[string(pending)]++
					pending = pending[:0]
				}
				i++
				continue
			}
			start := i
			for i < len(chunk) && isLetter(chunk[i]) {
				chunk[i] |= 0x20
				i++
			}
			word := chunk[start:i]
			switch {
			case len(pending) == 0 && i < len(chunk):
				// Fast path: the word lies entirely within this chunk.
				// The string conversion in the map index does not allocate.
				counts[string(word)]++
			case i < len(chunk):
				pending = append(pending, word...)
				counts[string(pending)]++
				pending = pending[:0]
			default:
				pending = append(pending, word...)
			}
		}
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}
	}
	if len(pending) > 0 {
		counts[string(pending)]++
	}
	return counts, nil
}

// compareRank orders by count descending, then by word ascending.
func compareRank(a, b WordCount) int {
	if c := cmp.Compare(b.Count, a.Count); c != 0 {
		return c
	}
	return cmp.Compare(a.Word, b.Word)
}

// Top returns up to n entries of counts in rank order.
func Top(counts map[string]int, n int) []WordCount {
	top := make([]WordCount, 0, n+1)
	for w, c := range counts {
		e := WordCount{Word: w, Count: c}
		if len(top) == n && compareRank(e, top[n-1]) >= 0 {
			continue
		}
		pos, _ := slices.BinarySearchFunc(top, e, compareRank)
		top = slices.Insert(top, pos, e)
		if len(top) > n {
			top = top[:n]
		}
	}
	return top
}

func run(in io.Reader, out io.Writer) error {
	counts, err := CountWords(in)
	if err != nil {
		return fmt.Errorf("reading input: %w", err)
	}
	w := bufio.NewWriter(out)
	for _, e := range Top(counts, topN) {
		w.WriteString(strconv.Itoa(e.Count))
		w.WriteByte(' ')
		w.WriteString(e.Word)
		w.WriteByte('\n')
	}
	return w.Flush()
}

func main() {
	if err := run(os.Stdin, os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, "wordfreq:", err)
		os.Exit(1)
	}
}

package main

import (
	"bytes"
	"strings"
	"testing"
	"testing/iotest"
)

func TestRun(t *testing.T) {
	tests := []struct {
		name, in, want string
	}{
		{"simple", "The cat and the hat.", "2 the\n1 and\n1 cat\n1 hat\n"},
		{"empty", "", ""},
		{"no words", "123 _-' \xff\xc3(", ""},
		{"separators", "don't stop_me 4now, now-NOW", "3 now\n1 don\n1 me\n1 stop\n1 t\n"},
		{"top ten", "k j i h g f e d c b a a", "2 a\n1 b\n1 c\n1 d\n1 e\n1 f\n1 g\n1 h\n1 i\n1 j\n"},
		{"prefix order", "ab a abc", "1 a\n1 ab\n1 abc\n"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var out bytes.Buffer
			if err := run(strings.NewReader(tt.in), &out); err != nil {
				t.Fatal(err)
			}
			if got := out.String(); got != tt.want {
				t.Errorf("got %q, want %q", got, tt.want)
			}
		})
	}
}

func TestWordsSpanningReads(t *testing.T) {
	in := strings.Repeat("Hello wORld ", 1000) + "tail"
	var out bytes.Buffer
	if err := run(iotest.OneByteReader(strings.NewReader(in)), &out); err != nil {
		t.Fatal(err)
	}
	want := "1000 hello\n1000 world\n1 tail\n"
	if got := out.String(); got != want {
		t.Errorf("got %q, want %q", got, want)
	}
}
